import json

with open("/home/USER/runs/paper/qwen-hpl-u1-turns/frozen/seen/play/users/u056/system/state/workspace/programs/task-a787295d.json") as f:
    demos = json.load(f)

demo = demos[0]
input_grid = demo["input"]
output_grid = demo["output"]

h, w = len(input_grid), len(input_grid[0])

# Build output based on my analysis
def transform(input_grid):
    h, w = len(input_grid), len(input_grid[0])
    h2, w2 = 2*h, 2*w

    result = [[0]*w2 for _ in range(h2)]

    # TL: identity
    for r in range(h):
        for c in range(w):
            result[r][c] = input_grid[r][c]

    # TR: TR[r][c+6] based on TR = flipH(flipV(BL)) and BL = rot90(input)
    for r in range(h):
        for c in range(w):
            # TR[r][6+c] = BL[5-r][5-c]
            # BL[5-r][5-c] = input_grid[c][w-1-(5-r)]
            result[r][w+c] = input_grid[c][w-6+r]

    # BL: rot90 of input
    for r in range(h):
        for c in range(w):
            # output[6+r][c] = rot90(input)[r][c]
            # = input[c][w-1-r]
            result[6+r][c] = input_grid[c][w-1-r]

    # BR: center_map of input
    for r in range(h):
        for c in range(w):
            # output[6+r][6+c] = input[h-1-r][w-1-c]
            result[6+r][w+c] = input_grid[h-1-r][w-1-c]

    return result

# Build and compare
built = transform(input_grid)
match = built == output_grid
print(f"Built output matches: {match}")

if not match:
    for i in range(len(built)):
        for j in range(len(built[0])):
            if built[i][j] != output_grid[i][j]:
                print(f"Mismatch at [{i}][{j}]: built={built[i][j]}, actual={output_grid[i][j]}")

# Show built output
print("\nBuilt output:")
for row in built:
    print(row)

print("\nActual output:")
for row in output_grid:
    print(row)

